def make_palindrome(n, arr):
    operations = []
    i, j = 0, n - 1

    while i < j:
        if arr[i] < arr[j]:
            diff = arr[j] - arr[i]
            arr[i] += diff
            arr[i + 1] += diff
            operations.append((i + 1, diff))  # 记录操作
        elif arr[i] > arr[j]:
            diff = arr[i] - arr[j]
            arr[j] += diff
            arr[j - 1] += diff
            operations.append((j, diff))  # 记录操作
        i += 1
        j -= 1

    # 检查是否是回文数组
    if arr == arr[::-1]:
        print(len(operations))
        for op in operations:
            print(op[0], op[1])
    else:
        print(-1)

