### Java 实现

```java
import java.util.*;

public class Main {
    public static void makePalindrome(int n, long[] arr) {
        List<long[]> operations = new ArrayList<>();
        int i = 0, j = n - 1;

        while (i < j) {
            if (arr[i] < arr[j]) {
                long diff = arr[j] - arr[i];
                arr[i] += diff;
                arr[i + 1] += diff;
                operations.add(new long[]{i + 1, diff});
            } else if (arr[i] > arr[j]) {
                long diff = arr[i] - arr[j];
                arr[j] += diff;
                arr[j - 1] += diff;
                operations.add(new long[]{j, diff});
            }
            i++;
            j--;
        }

        // 检查是否是回文数组
        boolean isPalindrome = true;
        for (int k = 0; k < n / 2; k++) {
            if (arr[k] != arr[n - k - 1]) {
                isPalindrome = false;
                break;
            }
        }

        if (isPalindrome) {
            System.out.println(operations.size());
            for (long[] op : operations) {
                System.out.println(op[0] + " " + op[1]);
            }
        } else {
            System.out.println(-1);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextLong();
        }
        makePalindrome(n, arr);
    }
}
