def solve():
    import sys
    from collections import defaultdict
    input = sys.stdin.readline
    n = int(input())
    a = list(map(int, input().split()))
    ops = defaultdict(int)
    l, r = 0, n-1
    while l < r:
        if a[l] < a[r]:
            diff = a[r] - a[l]
            a[l] += diff
            a[l+1] += diff
            ops[l] += diff
        elif a[l] > a[r]:
            diff = a[l] - a[r]
            a[r] += diff
            a[r-1] += diff
            ops[r-1] += diff
        l += 1
        r -= 1
    # 检查是否镜像
    ok = True
    for i in range(n//2):
        if a[i] != a[n-1-i]:
            ok = False
            break
    if not ok:
        print(-1)
        return
    # 输出操作
    m = len(ops)
    print(m)
    # 按i顺序输出
    for i in sorted(ops.keys()):
        print(i+1, ops[i])

