Java代码：

import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextLong();
        Map<Integer, Long> ops = new HashMap<>();
        int l = 0, r = n-1;
        while (l < r) {
            if (a[l] < a[r]) {
                long diff = a[r] - a[l];
                a[l] += diff;
                a[l+1] += diff;
                ops.put(l, ops.getOrDefault(l, 0L) + diff);
            } else if (a[l] > a[r]) {
                long diff = a[l] - a[r];
                a[r] += diff;
                a[r-1] += diff;
                ops.put(r-1, ops.getOrDefault(r-1, 0L) + diff);
            }
            l++;
            r--;
        }
        boolean ok = true;
        for (int i = 0; i < n/2; i++) {
            if (a[i] != a[n-1-i]) { ok = false; break; }
        }
        if (!ok) {
            System.out.println(-1);
            return;
        }
        System.out.println(ops.size());
        // 按i升序输出
        List<Integer> keys = new ArrayList<>(ops.keySet());
        Collections.sort(keys);
        for (int i : keys) {
            System.out.println((i+1) + " " + ops.get(i));
        }
    }
}

